package io.lumine.mythic.lib.api.crafting.recipes.vmp; import io.lumine.mythic.lib.api.crafting.recipes.MythicRecipeStation; import java.util.*; public class SuperWorkbenchMapping extends VanillaInventoryMapping implements CustomInventoryCheck { public static final String SUPER_WORKBENCH="swb"; public static SuperWorkbenchMapping SWB; private static final int[] MAIN={1,2,3,4,5,10,11,12,13,14,19,20,21,22,23,28,29,30,31,32,37,38,39,40,41}; private static final int[] EDGE={0,9,18,27,36,6,15,24,33,42,7,16,34,43,8,17,26,35,44}; public SuperWorkbenchMapping(){SWB=this;} public int getMainWidth(int r){return 5;} public int getMainHeight(int c){return 5;} public int getMainSlot(int x,int y){if(x<0||x>=5||y<0||y>=5)throw outOfBounds(x,y);return MAIN[y*5+x];} public int getMainInventoryStart(){return 1;} public int getMainInventoryWidth(){return 5;} public int getMainInventoryHeight(){return 5;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 25;} public int getResultInventoryStart(){return 25;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==25;} public int getSideWidth(String n,int r){throw sideInventoryException(n);} public int getSideHeight(String n,int c){throw sideInventoryException(n);} public int getSideSlot(String n,int x,int y){throw sideInventoryException(n);} public int getSideInventoryStart(String n){throw sideInventoryException(n);} public int getSideInventoryWidth(String n){throw sideInventoryException(n);} public int getSideInventoryHeight(String n){throw sideInventoryException(n);} public boolean mainIsResult(){return false;} public MythicRecipeStation getIntendedStation(){return MythicRecipeStation.WORKBENCH;} public String getIntendedInventory(){return "CHEST_45";} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>();} public boolean isTargetInventory(int size,String key){return size==45&&SUPER_WORKBENCH.equalsIgnoreCase(key);} public String getCustomStationKey(){return SUPER_WORKBENCH;} public static ArrayList<Integer> getEdgeSlots(){ArrayList<Integer> out=new ArrayList<>();for(int i:EDGE)out.add(i);return out;} }
